#!/usr/bin/env python3
"""Assemble the body of a comparator `Challenge.lean` from the extractor's TSV.

Input: the TSV produced by ``extract_closure.lean`` (one declaration per row:
name, module path, start line, end line).  For each declaration this script
re-reads its source lines and records the namespace stack active at that
point (tracking ``namespace``/``section``/``end`` lines), orders declarations
topologically (module import rank, then line number), and emits the snippets
grouped under merged namespace blocks with provenance comments.

The elaboration context that the kernel closure cannot see (attribute commands,
``CoeFun`` instances, ``variable``/``open`` blocks) lives in the ``extras`` and
``module_preludes`` tables of the selected challenge configuration under
``challenges/``; the script fails if one of *that challenge's* keys no longer
matches any extracted declaration.  See README.md in this directory for the
full regeneration pipeline.
"""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

from challenge_config import (
    DEFAULT_CHALLENGE,
    ChallengeConfig,
    ChallengeConfigError,
    Prelude,
    load_challenges,
)

Entry = tuple[str, str, int, int, list[str]]


class StaleContextTables(ValueError):
    """A challenge's ``extras``/``module_preludes`` key matches no declaration."""


def source_range_with_context(
    lines: list[str], start: int, end: int
) -> tuple[int, list[str]]:
    """Extend a declaration range to include adjacent scoped context commands."""
    # Lean's source range starts at a declaration's docstring and can omit a
    # declaration-scoped command immediately before it.  Preserve that command:
    # dropping `open scoped Classical in`, for example, removes the local
    # decidability instances needed to re-elaborate the definition body.
    if start > 1 and re.fullmatch(r"open\s+scoped\s+.+\s+in", lines[start - 2].strip()):
        start -= 1
    return start, lines[start - 1 : end]


class Assembler:
    def __init__(
        self,
        repo_root: Path,
        extras: dict[str, list[str]] | None = None,
        module_preludes: dict[str, tuple[Prelude, ...]] | None = None,
    ) -> None:
        self.repo_root = repo_root
        self.extras = extras or {}
        self.module_preludes = module_preludes or {}
        self._file_cache: dict[str, list[str]] = {}
        self.out: list[str] = []
        self.cur_ns: list[str] = []
        self.open_prelude: tuple[str, Prelude] | None = None
        self.used_preludes: set[tuple[str, int]] = set()
        self._closure_cache: dict[str, set[str]] = {}

    def get_lines(self, path: str) -> list[str]:
        if path not in self._file_cache:
            text = (self.repo_root / path).read_text(encoding="utf-8")
            self._file_cache[path] = text.splitlines()
        return self._file_cache[path]

    def ns_stack_at(self, path: str, line_no: int) -> list[str]:
        """Namespace stack (list of names) active just before 1-indexed line_no."""
        stack: list[tuple[str, str | None]] = []
        for raw in self.get_lines(path)[: line_no - 1]:
            s = raw.strip()
            m = re.match(r"namespace\s+([\w.À-￿']+)", s)
            if m:
                stack.append(("ns", m.group(1)))
                continue
            m = re.match(r"section\s*([\w.À-￿']*)", s)
            if m and s.startswith("section"):
                stack.append(("sec", m.group(1) or None))
                continue
            m = re.match(r"end\s*([\w.À-￿']*)\s*(?:--.*)?$", s)
            if m and s.startswith("end") and stack:
                stack.pop()
        return [n for kind, n in stack if kind == "ns" and n is not None]

    def imports_of(self, path: str) -> list[str]:
        # imports are only legal at the top of a Lean file, so scanning the
        # whole file for ^import is safe and robust against comment headers
        return [
            m.group(1).replace(".", "/") + ".lean"
            for raw in self.get_lines(path)
            if (m := re.match(r"import\s+([\w.]+)", raw))
        ]

    def local_closure(self, path: str) -> set[str]:
        """All `MIPStarRE/...` modules `path` imports, transitively."""
        cached = self._closure_cache.get(path)
        if cached is not None:
            return cached
        self._closure_cache[path] = set()  # cycle guard
        out: set[str] = set()
        for dep in self.imports_of(path):
            if not dep.startswith("MIPStarRE/"):
                continue
            if not (self.repo_root / dep).exists():
                continue
            out.add(dep)
            out |= self.local_closure(dep)
        self._closure_cache[path] = out
        return out

    def module_ranks(self, mods: set[str]) -> dict[str, int]:
        rank: dict[str, int] = {}

        def visit(p: str, depth: int = 0) -> None:
            if p in rank or depth > 200:
                return
            rank[p] = -1  # in progress
            local = [d for d in self.imports_of(p) if d.startswith("MIPStarRE/")]
            for d in local:
                if rank.get(d) != -1:
                    visit(d, depth + 1)
            rank[p] = max((rank.get(d, 0) for d in local), default=0) + 1

        for p in sorted(mods):
            visit(p)
        return rank

    def switch_ns(self, target: list[str]) -> None:
        common = 0
        while (
            common < min(len(self.cur_ns), len(target))
            and self.cur_ns[common] == target[common]
        ):
            common += 1
        for n in reversed(self.cur_ns[common:]):
            self.out.append(f"end {n}")
        for n in target[common:]:
            self.out.append(f"namespace {n}")
        self.cur_ns = target

    def prelude_for(self, path: str, line: int) -> Prelude | None:
        """The configured scope of ``path`` covering ``line``, if any."""
        for prelude in self.module_preludes.get(path, ()):
            if prelude.covers(line):
                return prelude
        return None

    def close_prelude(self) -> None:
        if self.open_prelude:
            self.switch_ns(list(self.open_prelude[1].namespace))
            self.out.append("end  -- module scope")
            self.open_prelude = None

    def open_prelude_for(self, path: str, prelude: Prelude) -> None:
        self.switch_ns(list(prelude.namespace))
        label = path if prelude.whole_file else f"{path}:{prelude.first}-{prelude.last}"
        self.out.append("")
        self.out.append(f"-- elaboration context of {label}")
        self.out.append("noncomputable section" if prelude.noncomputable else "section")
        self.out.extend(prelude.lines)
        self.open_prelude = (path, prelude)
        self.used_preludes.add((path, prelude.first))

    def emit(self, entries: list[Entry], generated: list[tuple[str, str]]) -> str:
        # compiler-generated declarations (no source range) regenerate
        # identically during elaboration; record them up front as comments so
        # they never interact with namespace or prelude state
        if generated:
            self.out.append("-- Compiler-generated declarations in the closure (no source")
            self.out.append("-- range); they regenerate identically during elaboration:")
            for name, path in generated:
                self.out.append(f"--   {name}  (from {path})")

        emitted_ranges: set[tuple[str, int]] = set()
        # widest range emitted so far per module, to swallow the pieces of a
        # declaration that the closure reports separately
        enclosing: dict[str, tuple[int, int]] = {}
        for name, path, a, b, src in entries:
            if (path, a) in emitted_ranges:  # deriving twins share the range
                continue
            # a constructor's `.elim`/`.noConfusion`/`.injEq` companion and a
            # `deriving` clause report a range *inside* their inductive's
            # range; emitting those lines on their own is a syntax error, and
            # the inductive command regenerates them anyway
            outer = enclosing.get(path)
            if outer is not None and outer[0] <= a and b <= outer[1]:
                continue
            emitted_ranges.add((path, a))
            enclosing[path] = (a, b)
            prelude = self.prelude_for(path, a)
            if self.open_prelude and self.open_prelude != (path, prelude):
                self.close_prelude()
            if prelude is not None and self.open_prelude is None:
                self.open_prelude_for(path, prelude)
            self.switch_ns(self.ns_stack_at(path, a))
            self.out.append("")
            self.out.append(f"-- source: {path}:{a}-{b}  ({name})")
            self.out.extend(src)
            self.out.extend(self.extras.get(name, []))
        self.close_prelude()
        self.switch_ns([])
        return "\n".join(self.out)


MIRROR_ROOT = "Challenge"


def mirror_module(path: str) -> str:
    """`MIPStarRE/QPBT/Algebra/Pauli.lean` -> `Challenge.MIPStarRE.QPBT.Algebra.Pauli`."""
    return f"{MIRROR_ROOT}." + path.removesuffix(".lean").replace("/", ".")


def mirror_file(path: str) -> str:
    return f"{MIRROR_ROOT}/" + path


def optional_part_text(root: Path, relative: str | None) -> str:
    """A configured challenge part, or empty text when omitted or absent."""
    if relative is None:
        return ""
    path = root / relative
    return path.read_text(encoding="utf-8") if path.exists() else ""


class SplitAssembler(Assembler):
    """Emit one Mathlib-only challenge module per contributing library module.

    Lean caches an abstracted nested proof and a `match` auxiliary *per module*,
    keyed by the statement and named after the first declaration of that module
    that needs it, and a module only sees the instances its imports declare.  A
    single-file challenge therefore cannot reproduce either name when a library
    fact is needed in two library modules, and it makes every instance visible
    to every declaration.  Mirroring the library's module partition and import
    graph reproduces both by construction.
    """

    def module_body(self, path: str, entries: list[Entry]) -> str:
        self.out = []
        self.cur_ns = []
        self.open_prelude = None
        return self.emit(entries, [])


def minimal_mirror_imports(
    asm: SplitAssembler, path: str, contributing: set[str]
) -> list[str]:
    """Contributing modules `path` imports, with redundant ancestors dropped."""
    reach = {q for q in asm.local_closure(path) if q in contributing}
    minimal = [
        q
        for q in reach
        if not any(r != q and q in asm.local_closure(r) for r in reach)
    ]
    return sorted(minimal)


def assemble_split(
    challenge: ChallengeConfig, root: Path, tsv: Path
) -> dict[str, str]:
    """Return {path relative to the challenge repository: file contents}."""
    asm = SplitAssembler(root, challenge.extras, challenge.module_preludes)
    entries, generated = read_entries(asm, tsv)

    rank = asm.module_ranks({e[1] for e in entries})
    entries.sort(key=lambda e: (rank.get(e[1], 999), e[1], e[2]))

    by_module: dict[str, list[Entry]] = {}
    for entry in entries:
        by_module.setdefault(entry[1], []).append(entry)
    contributing = set(by_module)
    ordered = sorted(contributing, key=lambda m: (rank.get(m, 999), m))

    opens = list(challenge.common_opens)
    files: dict[str, str] = {}
    for path in ordered:
        deps = minimal_mirror_imports(asm, path, contributing)
        head = ["import Mathlib"] + [f"import {mirror_module(d)}" for d in deps]
        head += [
            "",
            f"/-! Challenge mirror of `{path}`.",
            "",
            "One challenge module per contributing library module, importing the",
            "mirrors of the library modules this one imports.  The partition is",
            "what makes Lean generate the same auxiliary declarations, under the",
            "same names, as the library does. -/",
            "",
        ]
        head += opens
        body = asm.module_body(path, by_module[path])
        files[mirror_file(path)] = "\n".join(head) + "\n" + body + "\n"

    header = optional_part_text(root, challenge.header)
    footer = optional_part_text(root, challenge.footer)
    part_imports = "\n".join(f"import {mirror_module(m)}" for m in ordered)
    marker = "import Mathlib\n"
    if not header:
        header = marker
    elif marker not in header:
        raise SystemExit("challenge header must start with `import Mathlib`")
    header = header.replace(marker, marker + part_imports + "\n", 1)

    lines: list[str] = []
    if generated:
        lines.append("-- Compiler-generated declarations in the closure (no source")
        lines.append("-- range); they regenerate identically during elaboration:")
        for name, gpath in generated:
            lines.append(f"--   {name}  (from {gpath})")
        lines.append("")
    files["Challenge.lean"] = header + "\n".join(lines) + footer

#!/usr/bin/env python3
"""Per-challenge configuration for the comparator challenge generator.

A *challenge* is one self-contained `Challenge.lean` file: the Lean modules the
extractor must import, the target theorems whose statement closure it extracts,
the header and footer wrapped around the assembled body, the checked-in
expected copy, and the elaboration-context tables (`extras`,
`module_preludes`) that the kernel closure cannot see.

Configurations live in `scripts/comparator/challenges/<name>.json` and are read
by `extract_closure.lean` (through the environment), `assemble_challenge.py`
and `check_challenge_drift.py`.  See README.md in this directory.

Schema (unknown top-level keys are rejected so typos fail loudly):

```jsonc
{
  "name": "ldt",                       // required, must equal the file stem
  "description": "…",                  // optional, free text
  "imports": ["MIPStarRE.…"],          // required, non-empty
  "targets": ["MIPStarRE.…"],          // required, non-empty; closure roots
  "header": "scripts/…/header.lean",   // optional, null to omit
  "footer": "scripts/…/footer.lean",   // optional, null to omit
  "expected": "scripts/…/Challenge.lean.expected",   // required
  "require_expected": true,            // optional, default true
  "split": false,                      // optional, default false
  "common_opens": ["open scoped …"],  // optional, split-module context
  "extras": {"Decl.Name": ["line"]},   // optional
  "module_preludes": {                 // optional
    // one scope covering the whole module …
    "MIPStarRE/…/Module.lean": {"namespace": ["A", "B"], "lines": ["open …"]},
    // … or several, each covering a line range of it
    "MIPStarRE/…/Other.lean": [
      {"namespace": ["A"], "lines": ["variable …"], "first": 52, "last": 94},
      {"namespace": ["A"], "lines": ["variable …"], "first": 96, "last": 223,
       "noncomputable": true}
    ]
  }
}
```

A module needs one scope per source section whose elaboration context differs:
the self-dual normal basis file, for instance, has a group-algebra section and
a trace-dual section binding the same identifier to different things.  A scope
opened with `noncomputable section` in the source is marked `noncomputable`,
because the definitions inside such a section carry no `noncomputable` keyword
of their own and do not re-elaborate outside one.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any

# Configuration lives next to the scripts that read it, not under the tree
# being checked: `--root` names the library tree, which may be a different
# worktree than the one these scripts were invoked from.
CHALLENGE_DIR = Path(__file__).resolve().parent / "challenges"
DEFAULT_CHALLENGE = "ldt"

# Read by `extract_closure.lean`; comma-separated fully qualified names.
TARGETS_ENV = "MIPSTARRE_COMPARATOR_TARGETS"

# `last` of a scope that runs to the end of its module
LAST_LINE = 10**9

_NAME_RE = re.compile(r"[a-z0-9][a-z0-9_-]*\Z")

_KEYS = {
    "name",
    "description",
    "imports",
    "targets",
    "header",
    "footer",
    "expected",
    "require_expected",
    "split",
    "common_opens",
    "extras",
    "module_preludes",
}

_PRELUDE_KEYS = {"namespace", "lines", "first", "last", "noncomputable"}


class ChallengeConfigError(ValueError):
    """A challenge configuration is missing a key, or a key has a wrong type."""


@dataclass(frozen=True)
class Prelude:
    """Elaboration context of one source scope of one module.

    The `open`s, `variable`s and `local notation` that the declarations of a
    source section were elaborated under, replayed around the snippets taken
    from lines `first`..`last` of that module.
    """

    namespace: tuple[str, ...]
    lines: tuple[str, ...]
    first: int = 1
    last: int = LAST_LINE
    noncomputable: bool = False

    @property
    def whole_file(self) -> bool:
        return self.first == 1 and self.last == LAST_LINE

    def covers(self, line: int) -> bool:
        return self.first <= line <= self.last


@dataclass(frozen=True)
class ChallengeConfig:
    """One comparator challenge, as configured on disk."""

    name: str
    path: Path
    description: str
    imports: tuple[str, ...]
    targets: tuple[str, ...]
    header: str | None
    footer: str | None
    expected: str
    require_expected: bool
    split: bool
    common_opens: tuple[str, ...]
    extras: dict[str, list[str]]
    module_preludes: dict[str, tuple[Prelude, ...]]

    def import_block(self) -> str:
        """The extractor's module header for this challenge."""
        return "".join(f"import {module}\n" for module in self.imports)

    def extractor_env(self) -> dict[str, str]:
        """Environment overrides telling the extractor which targets to close."""
        return {TARGETS_ENV: ",".join(self.targets)}


def _typed(data: dict[str, Any], key: str, kind: type, where: Path) -> Any:
    if key not in data:
        raise ChallengeConfigError(f"{where}: missing required key {key!r}")
    value = data[key]
    if not isinstance(value, kind):
        raise ChallengeConfigError(
            f"{where}: key {key!r} must be {kind.__name__}, got {type(value).__name__}"
        )
    return value


def _string_list(data: dict[str, Any], key: str, where: Path, *, nonempty: bool) -> tuple[str, ...]:
    value = _typed(data, key, list, where)
    if not all(isinstance(item, str) for item in value):
        raise ChallengeConfigError(f"{where}: key {key!r} must be a list of strings")
    if nonempty and not value:
        raise ChallengeConfigError(f"{where}: key {key!r} must not be empty")
    return tuple(value)


def _optional_path(data: dict[str, Any], key: str, where: Path) -> str | None:
    value = data.get(key)
    if value is None:
        return None
    if not isinstance(value, str):
        raise ChallengeConfigError(f"{where}: key {key!r} must be a string or null")
    return value


def _extras(data: dict[str, Any], where: Path) -> dict[str, list[str]]:
    raw = data.get("extras", {})
    if not isinstance(raw, dict):
        raise ChallengeConfigError(f"{where}: key 'extras' must be an object")
    table: dict[str, list[str]] = {}
    for name, lines in raw.items():
        if not isinstance(lines, list) or not all(isinstance(line, str) for line in lines):
            raise ChallengeConfigError(
                f"{where}: extras[{name!r}] must be a list of source lines"
            )
        table[name] = list(lines)
    return table


def _prelude(entry: Any, module: str, where: Path) -> Prelude:
    if not isinstance(entry, dict):
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}] must be an object with "
            "'namespace' and 'lines', or a list of such objects"
        )
    unknown = sorted(set(entry) - _PRELUDE_KEYS)
    if unknown:
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}] has unknown key(s) {unknown}"
        )
    namespace = entry.get("namespace", [])
    lines = entry.get("lines", [])
    for field, value in (("namespace", namespace), ("lines", lines)):
        if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
            raise ChallengeConfigError(
                f"{where}: module_preludes[{module!r}][{field!r}] must be a list of strings"
            )
    first = entry.get("first", 1)
    last = entry.get("last", LAST_LINE)
    for field, value in (("first", first), ("last", last)):
        if not isinstance(value, int) or isinstance(value, bool) or value < 1:
            raise ChallengeConfigError(
                f"{where}: module_preludes[{module!r}][{field!r}] must be a positive integer"
            )
    if last < first:
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}] has 'last' before 'first'"
        )
    noncomputable = entry.get("noncomputable", False)
    if not isinstance(noncomputable, bool):
        raise ChallengeConfigError(
            f"{where}: module_preludes[{module!r}]['noncomputable'] must be a boolean"
        )
    return Prelude(
        namespace=tuple(namespace),
        lines=tuple(lines),
        first=first,
        last=last,
        noncomputable=noncomputable,
    )


def _module_preludes(data: dict[str, Any], where: Path) -> dict[str, tuple[Prelude, ...]]:
    raw = data.get("module_preludes", {})
    if not isinstance(raw, dict):
        raise ChallengeConfigError(f"{where}: key 'module_preludes' must be an object")
    table: dict[str, tuple[Prelude, ...]] = {}
    for module, entry in raw.items():
        entries = entry if isinstance(entry, list) else [entry]
        scopes = tuple(_prelude(item, module, where) for item in entries)
        if not scopes:
            raise ChallengeConfigError(
                f"{where}: module_preludes[{module!r}] must name at least one scope"
            )
        spans = sorted((scope.first, scope.last) for scope in scopes)
        for (_, earlier_last), (later_first, _) in zip(spans, spans[1:]):
            if later_first <= earlier_last:
                raise ChallengeConfigError(
                    f"{where}: module_preludes[{module!r}] has overlapping scopes; "
                    "one line of a module can only be elaborated in one context"
                )
        table[module] = scopes
    return table


def load_challenge(path: Path) -> ChallengeConfig:
    """Read and validate one challenge configuration file."""
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ChallengeConfigError(f"{path}: no such challenge configuration") from exc
    except json.JSONDecodeError as exc:
        raise ChallengeConfigError(f"{path}: invalid JSON — {exc}") from exc
    if not isinstance(data, dict):
        raise ChallengeConfigError(f"{path}: top level must be an object")

    unknown = sorted(set(data) - _KEYS)
    if unknown:
        raise ChallengeConfigError(f"{path}: unknown key(s) {unknown}")

    name = _typed(data, "name", str, path)
    if not _NAME_RE.match(name):
        raise ChallengeConfigError(
            f"{path}: name {name!r} must match {_NAME_RE.pattern} (it names the CLI selector)"
        )
    if name != path.stem:
        raise ChallengeConfigError(f"{path}: name {name!r} must equal the file stem {path.stem!r}")

    require_expected = data.get("require_expected", True)
    if not isinstance(require_expected, bool):
        raise ChallengeConfigError(f"{path}: key 'require_expected' must be a boolean")

    split = data.get("split", False)
    if not isinstance(split, bool):
        raise ChallengeConfigError(f"{path}: key 'split' must be a boolean")

    common_opens = data.get("common_opens", [])
    if not isinstance(common_opens, list) or not all(
        isinstance(line, str) for line in common_opens
    ):
        raise ChallengeConfigError(
            f"{path}: key 'common_opens' must be a list of strings"
        )

    return ChallengeConfig(
        name=name,
        path=path,
        description=str(data.get("description", "")),
        imports=_string_list(data, "imports", path, nonempty=True),
        targets=_string_list(data, "targets", path, nonempty=True),
        header=_optional_path(data, "header", path),
        footer=_optional_path(data, "footer", path),
        expected=_typed(data, "expected", str, path),
        require_expected=require_expected,
        split=split,
        common_opens=tuple(common_opens),
        extras=_extras(data, path),
        module_preludes=_module_preludes(data, path),
    )


def challenge_paths(directory: Path | None = None) -> list[Path]:
    """Every configuration file, in a deterministic (file name) order."""
    return sorted((directory or CHALLENGE_DIR).glob("*.json"))


